using Astronomy.MediaFactory.Core.KnowledgeFoundation.Catalog;using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Integration;using Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation;using Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.CrossDomain;using Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.Graph;using Microsoft.Extensions.DependencyInjection;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Catalog;
public sealed class AstronomyKnowledgeCatalogRegistrationTests{[Fact]public void AddAstronomyKnowledgeCatalog_is_idempotent_and_singleton(){var services=new ServiceCollection();services.AddAstronomyKnowledgeCatalog();services.AddAstronomyKnowledgeCatalog();Assert.Equal(1,services.Count(d=>d.ServiceType==typeof(IAstronomyKnowledgeCatalogBuilder)));Assert.Equal(1,services.Count(d=>d.ServiceType==typeof(IAstronomyKnowledgeCatalog)));using var p=services.BuildServiceProvider();Assert.Same(p.GetRequiredService<IAstronomyKnowledgeCatalog>(),p.GetRequiredService<IAstronomyKnowledgeCatalog>());Assert.NotNull(p.GetRequiredService<IAstronomyTypedPayloadRegistry>());Assert.NotNull(p.GetRequiredService<IAstronomyKnowledgeValidationRuleRegistry>());Assert.NotNull(p.GetRequiredService<IAstronomyCrossDomainValidationRuleRegistry>());Assert.NotNull(p.GetRequiredService<IAstronomyKnowledgeGraphValidationRuleRegistry>());}}
